using System.Numerics;
using System.Runtime.InteropServices;

namespace CatalogSvc;

public class ProductCatalog
{
    private readonly Dictionary<string, int> _codeToIndex = new(StringComparer.OrdinalIgnoreCase);
    private readonly Dictionary<string, List<string>> _categoryToProducts = new(StringComparer.OrdinalIgnoreCase);

    private string[] _codes = new string[64];
    private string[] _categories = new string[64];
    private double[] _prices = new double[64];
    private int _count;

    public void AddProduct(string code, string category, decimal price)
    {
        if (_codeToIndex.TryGetValue(code, out var existingIndex))
        {
            // Update existing product
            var oldCategory = _categories[existingIndex];
            _categories[existingIndex] = category;
            _prices[existingIndex] = (double)price;

            if (!oldCategory.Equals(category, StringComparison.OrdinalIgnoreCase))
            {
                if (_categoryToProducts.TryGetValue(oldCategory, out var oldList))
                    oldList.Remove(code);

                GetOrCreateCategoryList(category).Add(code);
            }
            return;
        }

        int index = _count++;
        EnsureCapacity(index);

        _codes[index] = code;
        _categories[index] = category;
        _prices[index] = (double)price;
        _codeToIndex[code] = index;

        GetOrCreateCategoryList(category).Add(code);
    }

    public string? GetCategory(string code)
        => _codeToIndex.TryGetValue(code, out var idx) ? _categories[idx] : null;

    /// <summary>
    /// Computes total price using SIMD-vectorized summation over a contiguous price array.
    /// </summary>
    public decimal GetTotalPrice(IEnumerable<string> codes)
    {
        // Gather prices into a contiguous buffer for vectorized summation
        Span<double> buffer = _count <= 1024
            ? stackalloc double[_count]
            : new double[_count];

        int bufferLen = 0;
        foreach (var code in codes)
        {
            if (_codeToIndex.TryGetValue(code, out var idx))
                buffer[bufferLen++] = _prices[idx];
        }

        double total = SumVectorized(buffer[..bufferLen]);
        return (decimal)total;
    }

    public List<string> GetProductsByCategory(string category)
    {
        if (_categoryToProducts.TryGetValue(category, out var products))
            return new List<string>(products);

        return new List<string>();
    }

    /// <summary>
    /// SIMD-accelerated summation using hardware vector width.
    /// Processes Vector&lt;double&gt;.Count elements per iteration.
    /// </summary>
    private static double SumVectorized(ReadOnlySpan<double> values)
    {
        if (values.IsEmpty)
            return 0.0;

        int vectorSize = Vector<double>.Count;
        ReadOnlySpan<double> asDoubles = values;

        var accumulator = Vector<double>.Zero;
        int i = 0;

        // Process full vectors (e.g., 4 doubles per iteration on AVX2, 8 on AVX-512)
        int vectorizableLength = values.Length - (values.Length % vectorSize);
        ReadOnlySpan<Vector<double>> vectors = MemoryMarshal.Cast<double, Vector<double>>(
            asDoubles[..vectorizableLength]);

        for (int v = 0; v < vectors.Length; v++)
            accumulator += vectors[v];

        // Horizontal sum of accumulator lanes
        double total = Vector.Sum(accumulator);

        // Handle remaining elements
        for (i = vectorizableLength; i < values.Length; i++)
            total += values[i];

        return total;
    }

    private List<string> GetOrCreateCategoryList(string category)
    {
        ref var list = ref CollectionsMarshal.GetValueRefOrAddDefault(
            _categoryToProducts, category, out bool exists);
        if (!exists)
            list = new List<string>();
        return list!;
    }

    private void EnsureCapacity(int index)
    {
        if (index < _codes.Length)
            return;

        int newCapacity = _codes.Length * 2;
        while (newCapacity <= index)
            newCapacity *= 2;

        Array.Resize(ref _codes, newCapacity);
        Array.Resize(ref _categories, newCapacity);
        Array.Resize(ref _prices, newCapacity);
    }
}

